const PREFIX = 'guides-book-';
const CACHE = PREFIX + PRECACHE.version;
const META = '__offline-meta__.json';
const BASE = self.registration.scope;                         // the book folder, ends with "/"
const abs = p => new URL(p, BASE).href;
const PARALLEL = 6;

async function tell(msg) {
  const clients = await self.clients.matchAll({ includeUncontrolled: true, type: 'window' });
  clients.forEach(c => c.postMessage(msg));
}

async function sha16(buf) {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', buf));
  return Array.from(d.slice(0, 8), b => b.toString(16).padStart(2, '0')).join('');
}

async function previousVersion() {                            // newest complete older cache
  const keys = (await caches.keys()).filter(k => k.startsWith(PREFIX) && k !== CACHE).reverse();
  for (const k of keys) {
    const c = await caches.open(k);
    const m = await c.match(abs(META));
    if (m) return { cache: c, files: (await m.json()).files || {} };
  }
  return null;
}

async function download(path, hash) {
  // ?v=<hash> gets past the browser and CDN caches, so right after a publish the fresh file arrives
  const res = await fetch(abs(path) + '?v=' + hash, { cache: 'reload' });
  if (!res.ok) throw new Error(path + ': HTTP ' + res.status);
  const buf = await res.arrayBuffer();
  if (await sha16(buf) !== hash) throw new Error(path + ' is not the published version yet');
  return new Response(buf, { headers: { 'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream' } });
}

async function install() {
  const cache = await caches.open(CACHE);
  const old = await previousVersion();
  const queue = Object.keys(PRECACHE.files);
  const total = queue.length;
  let done = 0, last = 0;
  async function worker() {
    while (queue.length) {
      const path = queue.shift(), hash = PRECACHE.files[path], key = abs(path);
      if (!(await cache.match(key))) {                        // not stored by an earlier, interrupted install
        const reuse = old && old.files[path] === hash ? await old.cache.match(key) : null;
        await cache.put(key, reuse || await download(path, hash));
      }
      done++;
      const now = Date.now();
      if (now - last > 400 || done === total) { last = now; tell({ type: 'offline-progress', done, total }); }
    }
  }
  await Promise.all(Array.from({ length: PARALLEL }, worker));
  await cache.put(abs(META), new Response(JSON.stringify(PRECACHE), { headers: { 'Content-Type': 'application/json' } }));
}

self.addEventListener('install', event => {
  event.waitUntil(install().then(() => self.skipWaiting(), err => {
    tell({ type: 'offline-error', message: String(err && err.message || err) });
    throw err;                                                // the browser retries on a later visit
  }));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
    tell({ type: 'offline-ready', version: PRECACHE.version });
  })());
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'offline-status' && event.source)
    event.source.postMessage({ type: 'offline-ready', version: PRECACHE.version });
});

async function respond(request) {
  const u = new URL(request.url);
  u.search = ''; u.hash = '';
  let key = u.href;
  if (key.endsWith('/')) key += 'index.html';
  const hit = await (await caches.open(CACHE)).match(key);
  if (hit) return hit;
  try {
    return await fetch(request);
  } catch (err) {
    if (request.mode === 'navigate') {
      return new Response('<!doctype html><meta name="viewport" content="width=device-width, initial-scale=1">' +
        '<p style="font:16px system-ui;margin:2rem">This page is not in the offline copy. ' +
        '<a href="' + BASE + 'index.html">Back to the book</a></p>', { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
    }
    throw err;
  }
}

self.addEventListener('fetch', event => {
  const r = event.request;
  if (r.method !== 'GET' || !r.url.startsWith(BASE)) return;
  event.respondWith(respond(r));
});
